INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1441547-gs342', 'stk-user10207', 'GS 342', 'info', '{"desc": "عليكم السلام.\n\nMass Media مذاكرتها من السلايدات. الدكتور الصيني غالباً يدرسها وهو كويس.\nInternational relations الصيف الماضي درسها مارك. الدكتور ممتاز. بس اعتقد المذاكرة من الكتاب وهو يحدد الاشياء المهمة.\n\nكلهم حلوين بس شوف وش الي يناسبك. بما انك تخصصك CS الـ Mass Media مواضيعها بتكون حلوة وسهلة لك.\n\nفي مادة ثانية خفيفة GS 336 - Work & Society اذا كانت محمد سعيد، سهالات والمذاكرة من السلايدات.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/gs-342-or-434-in-153/172157/2", "user": "user10207", "ts": 1454848906000, "tid": 172157, "pn": 2}}', 1454848906000, 1794792306, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
